"""The Larkspur Bikes support-ticket dataset, generated by fixed rules.

Larkspur Bikes wants every support ticket triaged into one JSON object:
`{"category", "priority", "bike", "order", "summary"}`. This script writes
240 train, 40 dev and 60 test tickets as OpenAI chat JSONL. No language model
is involved: each ticket is one of 20 issues, phrased from templates, and its
answer follows from the ticket's text by these rules:

- category: the issue's (billing, shipping, repair, warranty or sizing);
- priority: the issue's level (low, normal, high, urgent), where a late
  delivery is high from 10 days on; a stated deadline raises it one level;
- bike: the canonical model name, however the ticket spells it;
- order: `LK-` and the five digits the ticket gives, or null;
- summary: the issue's summary sentence with the bike's name.

The same seed writes the same bytes. Tune learning rates and epochs on dev only.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import random
from pathlib import Path

SPLITS = (("train", 240), ("dev", 40), ("test", 60))
"""Each split and its size, in the order tickets are drawn."""
LEVELS = ("low", "normal", "high", "urgent")
"""The priorities, lowest first; a deadline moves a ticket one step right."""

BIKES = {
    "Trail 29": ["Trail 29", "Larkspur Trail 29", "trail 29", "Trail29"],
    "Gravel GX": ["Gravel GX", "Larkspur Gravel GX", "gravel GX", "GX gravel bike"],
    "Commuter 7": ["Commuter 7", "Larkspur Commuter 7", "commuter 7", "Commuter7"],
    "Road SL": ["Road SL", "Larkspur Road SL", "road SL", "SL road bike"],
    "E-City": ["E-City", "Larkspur E-City", "e-city", "E City e-bike"],
    "Kids 20": ["Kids 20", "Larkspur Kids 20", "kids 20", "Kids 20 inch bike"],
}
"""Canonical bike names and the ways customers write them."""

# Each issue: category, priority (or "days" for the late-delivery rule), whether
# the ticket gives an order number ("always", "never", "often"), the summary,
# and the ways customers describe it. {bike} is the bike as the customer writes it.
ISSUES = [
    ("billing", "high", "always", "Charged twice for {bike} order.", [
        "I was charged twice for my {bike}.",
        "My card statement shows two payments for the same {bike}.",
        "You billed me two times for one {bike}, please fix this.",
    ]),
    ("billing", "normal", "always", "Refund not received for returned {bike}.", [
        "I returned my {bike} three weeks ago and the refund still has not arrived.",
        "Still waiting on the refund for the {bike} I sent back.",
        "Where is my refund? The {bike} went back to you a while ago.",
    ]),
    ("billing", "normal", "often", "Sale price not applied to {bike}.", [
        "The {bike} was on sale but I was charged the full price.",
        "I paid full price for my {bike} even though the site showed a discount.",
        "The discount on the {bike} did not apply at checkout.",
    ]),
    ("billing", "low", "always", "Invoice requested for {bike}.", [
        "Could you send me an invoice for my {bike}? I need it for my employer.",
        "I need a VAT invoice for the {bike} I bought.",
        "Please email me a receipt for the {bike}.",
    ]),
    ("shipping", "days", "always", "{bike} delivery is late.", [
        "My {bike} has not arrived yet and it has been {days} days.",
        "It is {days} days since I ordered the {bike} and tracking has not moved.",
        "Still no {bike} after {days} days. Where is it?",
    ]),
    ("shipping", "high", "always", "{bike} arrived damaged in shipping.", [
        "The {bike} arrived with a crushed box and a bent rear wheel.",
        "My {bike} came today but the frame is scratched and the derailleur is bent from the box.",
        "The courier dropped the box and my {bike} arrived damaged.",
    ]),
    ("shipping", "high", "always", "Wrong bike delivered instead of {bike}.", [
        "I ordered a {bike} but you sent me a completely different bike.",
        "The box had the wrong bike in it, not the {bike} I paid for.",
        "This is not my {bike}, I received someone else's model.",
    ]),
    ("shipping", "normal", "always", "Delivery address change for {bike}.", [
        "Can I change the delivery address for my {bike}? I am moving next week.",
        "Please ship the {bike} to my office instead of my home.",
        "I typed the wrong street for the {bike} delivery, can you update it?",
    ]),
    ("repair", "urgent", "often", "Brake failure on {bike}.", [
        "The brakes on my {bike} stopped working on a descent.",
        "My {bike} front brake has no bite at all anymore, I almost crashed.",
        "The rear brake lever on the {bike} goes all the way to the bar and does nothing.",
    ]),
    ("repair", "normal", "often", "Gears skipping on {bike}.", [
        "The gears on my {bike} skip when I pedal hard.",
        "My {bike} keeps jumping between gears on hills.",
        "Shifting on the {bike} is rough and the chain skips.",
    ]),
    ("repair", "low", "often", "Repeated flat tires on {bike}.", [
        "I keep getting flat tires on my {bike}.",
        "Third puncture this month on the {bike}, is something wrong with the rims?",
        "The tubes on my {bike} go flat every few days.",
    ]),
    ("repair", "normal", "often", "Clicking noise from {bike} bottom bracket.", [
        "There is a clicking noise from the bottom bracket of my {bike}.",
        "My {bike} clicks every time I push the pedals.",
        "A loud creak comes from the cranks of the {bike} on every stroke.",
    ]),
    ("warranty", "urgent", "often", "Cracked frame on {bike}.", [
        "I found a crack in the frame of my {bike} near the head tube.",
        "There is a hairline crack on the {bike} frame by the seat tube.",
        "My {bike} frame has cracked at a weld.",
    ]),
    ("warranty", "low", "often", "Paint peeling on {bike}.", [
        "The paint is peeling off my {bike}.",
        "Big flakes of paint are coming off the {bike} top tube.",
        "My {bike} paint started bubbling and chipping after two months.",
    ]),
    ("warranty", "high", "often", "Leaking fork on {bike}.", [
        "The fork on my {bike} is leaking oil.",
        "There is oil running down the fork legs of my {bike}.",
        "My {bike} suspension fork leaks and has gone soft.",
    ]),
    ("warranty", "normal", "often", "Battery no longer charges on {bike}.", [
        "The battery of my {bike} no longer holds a charge.",
        "My {bike} battery dies after a few kilometers now.",
        "The {bike} battery will not charge past one bar.",
    ]),
    ("sizing", "low", "never", "Frame size question for {bike}.", [
        "I am {height} cm tall, which frame size of the {bike} should I get?",
        "What size {bike} fits a rider who is {height} cm?",
        "Before I buy the {bike}: I am {height} cm, medium or large?",
    ]),
    ("sizing", "normal", "always", "Size exchange requested for {bike}.", [
        "The {bike} I got is too big, can I exchange it for a smaller frame?",
        "My {bike} is too small for me, I would like the next size up.",
        "Can I swap my {bike} for a different frame size?",
    ]),
    ("sizing", "low", "never", "Fit question about {bike} for a growing child.", [
        "Will the {bike} still fit my kid next year? She is growing fast.",
        "My son is {kid} cm, how long will the {bike} fit him?",
        "Is the {bike} a good size for a child who is {kid} cm and growing?",
    ]),
    ("sizing", "normal", "often", "Fit problem with {bike} reach.", [
        "My back hurts after riding the {bike}, is the reach too long for me?",
        "I feel too stretched out on my {bike}.",
        "My hands go numb on the {bike}, I think the fit is wrong.",
    ]),
]

GREETINGS = ["", "Hi. ", "Hello! ", "Hi there. ", "Good morning. ", "Hey! "]
ORDER_FORMATS = ["Order LK-{n}.", "My order number is {n}.", "Order #{n}.", "This is about order LK-{n}.",
                 "Order number: LK{n}."]
DEADLINES = ["I need it for a race this Saturday.", "We leave on a trip in two days.",
             "I need it for my commute on Monday.", "My event is this weekend."]
EXTRAS = ["", "", "Otherwise I love the bike.", "Please help.", "I have attached photos.",
          "Thanks for your help.", "This is really frustrating."]
SIGNOFFS = ["", "", " Thanks, Maya", " Best, Tom", " Cheers, Priya", " Regards, Lukas", " - Ana"]


def ticket(rng: random.Random) -> tuple[str, dict]:
    """One ticket's text and the answer the rules give it."""
    category, level, has_order, summary, phrasings = rng.choice(ISSUES)
    bike = rng.choice(sorted(BIKES))
    days, height, kid = rng.randint(3, 20), rng.randint(150, 195), rng.randint(100, 150)
    if level == "days":
        level = "high" if days >= 10 else "normal"
    issue = rng.choice(phrasings).format(bike=rng.choice(BIKES[bike]), days=days, height=height, kid=kid)
    order = None
    if has_order == "always" or (has_order == "often" and rng.random() < 0.7):
        order = f"{rng.randint(10000, 99999)}"
    deadline = rng.random() < 0.25
    parts = [issue]
    if order:
        parts.insert(rng.randint(0, 1), rng.choice(ORDER_FORMATS).format(n=order))
    if deadline:
        parts.append(rng.choice(DEADLINES))
        level = LEVELS[min(LEVELS.index(level) + 1, len(LEVELS) - 1)]
    parts.append(rng.choice(EXTRAS))
    text = (rng.choice(GREETINGS) + " ".join(p for p in parts if p) + rng.choice(SIGNOFFS)).strip()
    answer = {"category": category, "priority": level, "bike": bike,
              "order": f"LK-{order}" if order else None, "summary": summary.format(bike=bike)}
    return text, answer


def main() -> None:
    """Write the train, dev and test splits as chat JSONL."""
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--seed", type=int, default=7)
    parser.add_argument("--out", default=str(Path(__file__).parent / "data"))
    args = parser.parse_args()
    rng = random.Random(args.seed)
    seen, rows = set(), []
    while len(rows) < sum(n for _, n in SPLITS):
        text, answer = ticket(rng)
        if text in seen:
            continue
        seen.add(text)
        rows.append({"messages": [{"role": "user", "content": f"Triage this ticket: {text}"},
                                  {"role": "assistant", "content": json.dumps(answer)}]})
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    start = 0
    for name, n in SPLITS:
        data = "".join(json.dumps(r) + "\n" for r in rows[start : start + n]).encode()
        (out / f"{name}.jsonl").write_bytes(data)
        print(f"{hashlib.sha256(data).hexdigest()}  {out / f'{name}.jsonl'}  ({n} tickets)")
        start += n


if __name__ == "__main__":
    main()
